def investigate(context, acquire):
    actions = context.get('actions')
    if actions is None:
        actions = []
    present = set()
    high = 0
    open_transaction = False
    saved_present = set()
    saved_high = 0
    for action in actions:
        op = action.get('op')
        if op == 'put':
            value = action.get('id')
            present.add(value)
            if value > high:
                high = value
        elif op == 'delete':
            value = action.get('id')
            present.discard(value)
        elif op == 'begin':
            open_transaction = True
            saved_present = present.copy()
            saved_high = high
        elif op == 'commit':
            open_transaction = False
        elif op == 'rollback':
            open_transaction = False
            present = saved_present.copy()
            high = saved_high
    return high + 1

