                rows.remove(ident)
            if open_tx:
                pending.append(('delete', ident))
        elif op == 'begin':
            open_tx = True
            pending = []
        elif op == 'commit':
            open_tx = False
            pending = []
        elif op == 'rollback':
            for item in reversed(pending):
                kind = item[0]
