def investigate(context, acquire):
    seen = set()
    for row in context.get('examples', []):
        item = row.get('input') if isinstance(row, dict) else row
        if isinstance(item, dict):
            seen.add(repr(item))
    for row in context.get('receipts', []):
        item = row.get('query') if isinstance(row, dict) else None
        if isinstance(item, dict):
            seen.add(repr(item))
    candidates = [
        {"actions": [{"op": "put", "id": 1000}]},
        {"actions": [{"op": "begin"}, {"op": "put", "id": 1000}, {"op": "commit"}]},
        {"actions": [{"op": "put", "id": 1}, {"op": "begin"}, {"op": "put", "id": 1000}, {"op": "rollback"}]},
        {"actions": [{"op": "begin"}, {"op": "put", "id": 1000}, {"op": "rollback"}]},
        {"actions": [{"op": "put", "id": 1000}, {"op": "delete", "id": 1000}]},
        {"actions": [{"op": "begin"}, {"op": "put", "id": 1000}, {"op": "commit"}, {"op": "delete", "id": 1000}]},
        {"actions": [{"op": "put", "id": 999}, {"op": "begin"}, {"op": "put", "id": 1000}]},
        {"actions": [{"op": "put", "id": 1000}, {"op": "begin"}, {"op": "delete", "id": 1000}, {"op": "commit"}]}
    ]
    for candidate in candidates:
        if repr(candidate) not in seen:
            return {"query": candidate, "note": {"hypothesis": "AUTOINCREMENT tracks sqlite_sequence even across delete/rollback; boundary id 1000 discriminates max-rowid vs sequence models."}}
    return {"query": None, "note": {"reason": "all boundary candidates already covered"}}

